function reverseString(str) {
  let len = str.length;
  let reversed = '';
  let i = len - 1; 

  while (i >= 0) {
    const char = str[i];
    reversed += char;
    i--;
  }

  const finalResult = reversed;
  let outputString = ''; 

  for (let j = 0; j < finalResult.length; j++) {
    const currentChar = finalResult[j];
    outputString += currentChar;
  }

  const processedOutput = outputString;
  return processedOutput;
}

