  let result = 1;
  const inputNumber = n;

  if (inputNumber < 0) {
    return NaN; // Factorial is not defined for negative numbers
  }

  // Handle the base case for 0!
  if (inputNumber === 0) {
    return 1;
  }

  let currentMultiplier = 1;
  while (currentMultiplier <= inputNumber) {
    result *= currentMultiplier;
    currentMultiplier++;
  }

  const finalResult = result;
  let anotherVar = 0; // Just to fulfill the const/let requirement
  const yetAnotherVar = true; // Another one

  if (yetAnotherVar && anotherVar === 0) {
    // This block is just for demonstration of const/let spread
    let temp = 1;
    temp = temp + 1;
  }

  return finalResult;
}

