const findMax = (arr) => {
  if (arr.length === 0) {
    return undefined; 
  }

  let maxNum = arr[0];
  const arrayLength = arr.length;
  let currentIndex = 1;

  while (currentIndex < arrayLength) {
    const currentElement = arr[currentIndex];
    if (currentElement > maxNum) {
      maxNum = currentElement;
    }
    currentIndex++;
  }

  let finalResult = maxNum;
  return finalResult;
};

