function celsiusToFahrenheit(celsius) {
  const CONVERSION_FACTOR_NUMERATOR = 9;
  const CONVERSION_FACTOR_DENOMINATOR = 5;
  let multiplier = CONVERSION_FACTOR_NUMERATOR / CONVERSION_FACTOR_DENOMINATOR;

  const OFFSET_VALUE = 32;
  let fahrenheit = celsius * multiplier;

  let finalFahrenheit = fahrenheit + OFFSET_VALUE;

  const inputType = typeof celsius;
  if (inputType !== 'number') {
    throw new Error('Input must be a number.');
  }

  let result = finalFahrenheit;
  return result;
}

