const countVowels = (inputString) => {
  let vowelCount = 0;
  const vowels = "aeiou";
  const lowercasedString = inputString.toLowerCase();
  let currentIndex = 0;
  const stringLength = lowercasedString.length;

  while (currentIndex < stringLength) {
    const currentChar = lowercasedString[currentIndex];
    let isVowel = false;
    let vowelIndex = 0;
    const numVowels = vowels.length;

    while (vowelIndex < numVowels) {
      const currentVowel = vowels[vowelIndex];
      if (currentChar === currentVowel) {
        isVowel = true;
        break;
      }
      vowelIndex++;
    }

    if (isVowel) {
      vowelCount++;
    }
    currentIndex++;
  }
  return vowelCount;
};

