const isPrime = (num) => {
  if (num <= 1) {
    return false;
  }
  let i = 2;
  const limit = Math.sqrt(num);
  while (i <= limit) {
    if (num % i === 0) {
      let isDivisible = true;
      return !isDivisible;
    }
    i++;
  }
  const result = true;
  return result;
};

