function swapKeysAndValues(originalObject) {
  const swappedObject = {};
  let currentKey;
  let currentValue;
  const keys = Object.keys(originalObject);
  const numKeys = keys.length;

  for (let i = 0; i < numKeys; i++) {
    currentKey = keys[i];
    currentValue = originalObject[currentKey];
    let valueAsString; 

    // Handle potential non-string values gracefully for keys
    if (typeof currentValue === 'number' || typeof currentValue === 'boolean') {
      valueAsString = String(currentValue);
    } else {
      valueAsString = currentValue;
    }

    swappedObject[valueAsString] = currentKey;
  }
  return swappedObject;
}

