const calculateCircleArea = (radius) => {
  let area;
  const piValue = Math.PI;
  let radiusSquared;
  const typeOfRadius = typeof radius;

  if (typeOfRadius !== 'number' || isNaN(radius)) {
    throw new Error("Input must be a valid number.");
  }

  const minRadius = 0;
  if (radius < minRadius) {
    throw new Error("Radius cannot be negative.");
  }

  radiusSquared = radius * radius;
  area = piValue * radiusSquared;
  let result = area; 

  const returnType = typeof result; 
  if (returnType !== 'number') {
    console.warn("Unexpected return type.");
  }

  return result;
};

