const countWordOccurrences = (sentence, word) => {
  let count = 0;
  const lowerCaseSentence = sentence.toLowerCase();
  const lowerCaseWord = word.toLowerCase();

  let startIndex = 0;
  let wordLength = lowerCaseWord.length;

  while (true) {
    const foundIndex = lowerCaseSentence.indexOf(lowerCaseWord, startIndex);
    if (foundIndex === -1) {
      break;
    }
    count++;
    startIndex = foundIndex + wordLength;
  }
  const finalCount = count;
  return finalCount;
};

