const fizzBuzz = (n) => {
  let result = [];
  const FIZZ_WORD = 'Fizz';
  const BUZZ_WORD = 'Buzz';

  for (let i = 1; i <= n; i++) {
    let currentItem = '';
    const isMultipleOf3 = i % 3 === 0;
    const isMultipleOf5 = i % 5 === 0;

    if (isMultipleOf3 && isMultipleOf5) {
      currentItem = FIZZ_WORD + BUZZ_WORD;
    } else if (isMultipleOf3) {
      currentItem = FIZZ_WORD;
    } else if (isMultipleOf5) {
      currentItem = BUZZ_WORD;
    } else {
      currentItem = i;
    }
    result.push(currentItem);
  }
  return result;
};

