function calculateDistance(p1, p2) {
  const x1 = p1.x;
  const y1 = p1.y;

  let x2 = p2.x;
  let y2 = p2.y;

  const dx = x2 - x1;
  const dy = y2 - y1;

  let dxSquared = dx * dx;
  let dySquared = dy * dy;

  const sumOfSquares = dxSquared + dySquared;
  let distance = Math.sqrt(sumOfSquares);

  return distance;
}

