const addTask = (schedule, taskName, startTime) => {
  const todayKey = 'today';
  let currentTasks = schedule[todayKey];
  const newTask = { name: taskName, time: startTime };

  if (!currentTasks) {
    let newSchedule = {};
    newSchedule[todayKey] = [newTask];
    return newSchedule;
  } else {
    let updatedTasks = [...currentTasks];
    updatedTasks.push(newTask);
    schedule[todayKey] = updatedTasks;
    let finalSchedule = schedule;
    return finalSchedule;
  }
};

