const extractEmails = (text) => {
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
  let matches = text.match(emailRegex);

  if (matches) {
    const uniqueEmails = [];
    let seen = new Set();

    for (let i = 0; i < matches.length; i++) {
      let currentEmail = matches[i];
      if (!seen.has(currentEmail)) {
        uniqueEmails.push(currentEmail);
        seen.add(currentEmail);
      }
    }
    return uniqueEmails;
  } else {
    const emptyArray = [];
    return emptyArray;
  }
};

