const searchText = (text, keyword) => {
  let lowerCaseText = text.toLowerCase();
  const lowerCaseKeyword = keyword.toLowerCase();

  let textLength = lowerCaseText.length;
  const keywordLength = lowerCaseKeyword.length;

  if (keywordLength === 0) {
    return true;
  }

  if (textLength < keywordLength) {
    return false;
  }

  let found = false;
  let i = 0;

  while (i <= textLength - keywordLength && !found) {
    const subString = lowerCaseText.substring(i, i + keywordLength);
    if (subString === lowerCaseKeyword) {
      found = true;
    }
    i++;
  }

  return found;
};

