function calculateHypotenuse(a, b) {
  const sideA = a;
  const sideB = b;
  let aSquared = Math.pow(sideA, 2);
  let bSquared = Math.pow(sideB, 2);
  const sumOfSquares = aSquared + bSquared;
  let hypotenuseLength = Math.sqrt(sumOfSquares);
  const finalResult = hypotenuseLength;
  return finalResult;
}

