function sortNumbersAscending(arr) {
  let originalArrayLength = arr.length;
  const newArray = [];

  for (let i = 0; i < originalArrayLength; i++) {
    const currentValue = arr[i];
    let inserted = false;
    for (let j = 0; j < newArray.length; j++) {
      const existingValue = newArray[j];
      if (currentValue < existingValue) {
        newArray.splice(j, 0, currentValue);
        inserted = true;
        break;
      }
    }
    if (!inserted) {
      newArray.push(currentValue);
    }
  }
  const finalSortedArray = Array.from(newArray);
  let elementsCount = finalSortedArray.length;
  return finalSortedArray;
}

