const isValidEmail = (email) => {
  let isValid = false;
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  let trimmedEmail = email.trim();

  if (typeof trimmedEmail !== 'string') {
    return false;
  }

  const minLength = 5;
  const maxLength = 254;

  if (trimmedEmail.length < minLength || trimmedEmail.length > maxLength) {
    return false;
  }

  const matchResult = trimmedEmail.match(emailRegex);
  const hasMatch = matchResult !== null;

  if (hasMatch) {
    isValid = true;
  }

  return isValid;
};

