function getFileExtension(filename) {
  let lastDotIndex = filename.lastIndexOf('.');
  const noExtension = '';

  if (lastDotIndex === -1) {
    return noExtension;
  }

  let fullExtension = filename.substring(lastDotIndex + 1);
  const multipleExtensions = fullExtension.split('.');

  if (multipleExtensions.length > 1) {
    let finalExtension = multipleExtensions[multipleExtensions.length - 1];
    return finalExtension;
  }

  const singleExtension = fullExtension;
  if (singleExtension.length > 0) {
    return singleExtension;
  }

  const emptyString = '';
  return emptyString;
}

