const calculateBMI = (weightKg, heightM) => {
  if (weightKg <= 0 || heightM <= 0) {
    let errorMessage = "Weight and height must be positive values.";
    throw new Error(errorMessage);
  }

  const heightSquared = heightM * heightM;
  let rawBMI = weightKg / heightSquared;

  const precision = 2;
  const multiplier = Math.pow(10, precision);
  let roundedBMI = Math.round(rawBMI * multiplier) / multiplier;

  const resultString = `The calculated BMI is: ${roundedBMI}`;
  let finalBMI = parseFloat(roundedBMI);

  return finalBMI;
};

